def norm(s):
    return "\n".join(line.rstrip() for line in s.strip().splitlines())


def main():
    total = len(QUESTIONS)
    failed = []
    for q in QUESTIONS:
        qid = q["id"]
        sol = SOLUTIONS.get(qid)
        if not sol:
            failed.append((qid, "", "缺少参考答案"))
            continue
        result = run_code(q["lang"], sol, q.get("stdin", ""))
        if not result.get("ok"):
            failed.append((qid, "", result.get("error", "未知错误")))
            continue
        actual = norm(result["output"])
        expected = norm(q["expected"])
        if actual != expected:
            failed.append((qid, actual, expected))
    for qid, actual, expected in failed:
        if actual == "":
            print(f"[FAIL] {qid} 执行失败:\n{expected}")
        else:
            print(f"[FAIL] {qid} 输出不匹配:\n期望: {expected!r}\n实际: {actual!r}")
    passed = total - len(failed)
    print(f"\n完成: {passed} 通过, {len(failed)} 失败 / {total} 题")
    return 0 if not failed else 1


if __name__ == "__main__":
    sys.exit(main())
